from __future__ import annotations

import base64
import json
import os
import threading
import time
import webbrowser
from concurrent.futures import ThreadPoolExecutor
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

SOLVER_B64 = ''
HTML_B64 = ''

_solver_ns: dict = {}
exec(base64.b64decode(SOLVER_B64).decode("utf-8"), _solver_ns)
classify = _solver_ns["classify"]
result_to_dict = _solver_ns["result_to_dict"]
solve_game = _solver_ns["solve_game"]

HTML = base64.b64decode(HTML_B64).decode("utf-8")
EXECUTOR: ThreadPoolExecutor | None = None
SOLVE_CACHE: dict[str, dict] = {}


def solve_payload(payload: dict) -> dict:
    started = time.perf_counter()
    mine = payload.get("mine") or []
    enemy = payload.get("enemy") or []
    turn = payload.get("turn") or "mine"
    must_play = bool(payload.get("mustPlay"))
    split_rocket = bool(payload.get("splitRocket", True))
    fast = payload.get("fast")
    if fast is None:
        fast = True
    last = None
    last_move = payload.get("lastMove")
    if last_move and last_move.get("actor") != turn:
        cards = last_move.get("move", {}).get("cards", [])
        if cards:
            last = classify(cards)
    result = solve_game(mine, enemy, last=last, turn=turn, must_play=must_play, split_rocket=split_rocket, fast=bool(fast))
    data = result_to_dict(result)
    data["ms"] = round((time.perf_counter() - started) * 1000, 3)
    return data


class Handler(BaseHTTPRequestHandler):
    def log_message(self, format: str, *args) -> None:
        return

    def do_GET(self) -> None:
        path = urlparse(self.path).path
        if path not in {"/", "/doudizhu-endgame.html"}:
            self.send_error(404)
            return
        body = HTML.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self) -> None:
        if urlparse(self.path).path != "/api/solve":
            self.send_error(404)
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
            payload = json.loads(self.rfile.read(length).decode("utf-8") or "{}")
            cache_key = json.dumps(payload, ensure_ascii=False, sort_keys=True)
            cached = SOLVE_CACHE.get(cache_key)
            if cached is not None:
                data = dict(cached)
                data["cached"] = True
            elif EXECUTOR is None:
                data = solve_payload(payload)
            else:
                data = EXECUTOR.submit(solve_payload, payload).result()
            if cached is None:
                SOLVE_CACHE[cache_key] = dict(data)
                if len(SOLVE_CACHE) > 512:
                    SOLVE_CACHE.pop(next(iter(SOLVE_CACHE)))
            body = json.dumps(data, ensure_ascii=False).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except Exception as exc:
            body = json.dumps({"error": str(exc)}, ensure_ascii=False).encode("utf-8")
            self.send_response(400)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)


def main() -> None:
    global EXECUTOR
    EXECUTOR = ThreadPoolExecutor(max_workers=max(2, min(8, os.cpu_count() or 2)))
    port = 8765
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    url = f"http://127.0.0.1:{port}/"
    print("Dou Dizhu Endgame Calculator")
    print("Open:", url)
    print("Keep this window open. Close it to stop the app.")
    threading.Timer(0.6, lambda: webbrowser.open(url)).start()
    server.serve_forever()


if __name__ == "__main__":
    main()
